<?php
namespace App\Http\Controllers; use Illuminate\Support\Facades\{DB,Redis,Storage};
class HealthController extends Controller {public function live(){return ['status'=>'ok','service'=>'api','version'=>$this->version(),'time'=>now()->toIso8601String()];}public function ready(){try{DB::select('select 1');Redis::ping();return ['status'=>'ready','database'=>'ok','redis'=>'ok','version'=>$this->version()];}catch(\Throwable $e){return response()->json(['status'=>'not_ready','error'=>$e->getMessage(),'version'=>$this->version()],503);}}private function version():string{$runtime=trim((string)env('APP_VERSION',''));if($runtime!=='')return $runtime;$file=base_path('../../VERSION');return is_readable($file)?trim((string)file_get_contents($file)):'dev';}}
